require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='status'){$id=(int)$_POST['id'];$st=$pdo->prepare('UPDATE prayer_requests SET status=? WHERE id=?');$st->execute([$_POST['status']??'new',$id]);log_admin("Updated prayer request #$id");flash('admin_success','Prayer request status updated.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM prayer_requests WHERE id=?')->execute([$id]);log_admin("Deleted prayer request #$id");flash('admin_success','Prayer request deleted.');}}catch(Throwable $e){flash('admin_error','Prayer error: '.$e->getMessage());}redirect('admin/prayer.php');}$rows=$pdo->query('SELECT * FROM prayer_requests ORDER BY created_at DESC')->fetchAll();admin_page('Prayer Requests','prayer','Review requests privately and update their prayer status.');admin_flash();?><div class="admin-panel"><h2>Prayer Inbox</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Name</th><th>Email</th><th>Request</th><th>Visibility</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name']?:'Anonymous')?></td><td><?=e($r['email']?:'—')?></td><td style="max-width:360px"><?=e($r['request'])?></td><td><?=e($r['visibility'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><form method="post" style="display:flex;gap:5px;align-items:center"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>new</option><option>praying</option><option>answered</option><option>archived</option></select><button class="btn small outline">Save</button></form><form method="post" onsubmit="return confirm('Delete request?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
